def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = max(set(x for row in g for x in row), key=lambda x: sum(row.count(x) for row in g))

    # Find solid rectangular outlines, then color their interiors.
    for color in set(x for row in g for x in row):
        if color == bg:
            continue
        for r1 in range(h):
            for c1 in range(w):
                if g[r1][c1] != color:
                    continue
                for r2 in range(r1 + 2, h):
                    for c2 in range(c1 + 2, w):
                        if g[r2][c2] != color:
                            continue
                        if not all(g[r1][c] == color and g[r2][c] == color
                                   for c in range(c1, c2 + 1)):
                            continue
                        if not all(g[r][c1] == color and g[r][c2] == color
                                   for r in range(r1, r2 + 1)):
                            continue
                        ih, iw = r2 - r1 - 1, c2 - c1 - 1
                        fill = 7 if ih == iw and ih % 2 == 1 else 2
                        for r in range(r1 + 1, r2):
                            for c in range(c1 + 1, c2):
                                if g[r][c] == bg:
                                    g[r][c] = fill
    return g
